func renameCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "rename",
		Short: "Rename a feature or branch",
	}

	cmd.AddCommand(renameFeatureCmd())
	cmd.AddCommand(renameBranchCmd())

	return cmd
}

func renameFeatureCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "feature <old-name> <new-name>",
		Short: "Rename a feature",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			oldName := args[0]
			newName := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			var oldPath, newPath string
			if ws.Mode == internal.ModeCheckout {
				oldPath = ws.FeaturePath(oldName)
				newPath = ws.FeaturePath(newName)
			} else {
				oldPath = internal.FeaturePath(oldName)
				newPath = internal.FeaturePath(newName)
			}

			if _, err := os.Stat(oldPath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", oldName)
			}

			if _, err := os.Stat(newPath); err == nil {
				return fmt.Errorf("feature already exists: %s", newName)
			}

			if err := os.Rename(oldPath, newPath); err != nil {
				return fmt.Errorf("error renaming: %w", err)
			}

			fmt.Printf("Renamed feature: %s → %s\n", oldName, newName)
			return nil
		},
	}
}

func renameBranchCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "branch <feature> <old-name> <new-name>",
		Short: "Rename a branch within a feature",
		Args:  cobra.ExactArgs(3),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			feature := args[0]
			oldName := args[1]
			newName := args[2]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return renameBranchCheckout(ws, feature, oldName, newName)
			}
			return renameBranchExternal(feature, oldName, newName)
		},
	}
}

// renameBranchCheckout renames a branch in checkout mode.
// Uses entry.GitBranch() for git operations (honoring prefixes).
// Short Name is the metadata identity; git branch may have a prefix.
// Metadata is updated only after git succeeds; rolled back if SaveStack fails.
func renameBranchCheckout(ws internal.Workspace, feature, oldName, newName string) error {
	featurePath := ws.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	entry := internal.GetBranch(stack, oldName)
	if entry.Name == "" {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	oldGitBranch := entry.GitBranch()

	// Compute new git branch name: preserve prefix structure.
	cfg := internal.LoadConfig()
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	// Git rename using GitBranch() (the actual branch name, possibly prefixed).
	if err := internal.RunDir(ws.RepoRoot, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
		return fmt.Errorf("error renaming git branch %s -> %s: %w", oldGitBranch, newGitBranch, err)
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	// Update Branch field if the new git branch differs from the new name.
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		if rollbackErr := internal.RunSilentDir(ws.RepoRoot, "git", "branch", "-m", newGitBranch, oldGitBranch); rollbackErr != nil {
			return fmt.Errorf("error saving stack: %w; rollback of git branch also failed: %v", err, rollbackErr)
		}
		return fmt.Errorf("error saving stack (git branch rolled back): %w", err)
	}

	// Update decisions.yaml branch references.
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

// renameBranchExternal renames a branch in external mode.
// Uses entry.GitBranch() for git operations.
func renameBranchExternal(feature, oldName, newName string) error {
	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	if !internal.HasBranch(stack, oldName) {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	entry := internal.GetBranch(stack, oldName)
	oldGitBranch := entry.GitBranch()

	// Compute new git branch name preserving prefix.
	cfg := internal.LoadConfig()
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	gitDir := resolveGitDir(featurePath, stack)
	if gitDir == "" {
		return fmt.Errorf("could not find a git context; run from inside the repo or ensure at least one active worktree exists")
	}

	oldPath := internal.WorktreePath(feature, oldName)
	newPath := internal.WorktreePath(feature, newName)

	if _, err := os.Stat(oldPath); err == nil {
		// Active worktree: remove, rename branch, re-add
		if err := internal.RunDir(gitDir, "git", "worktree", "remove", "--force", oldPath); err != nil {
			return fmt.Errorf("error removing worktree: %w", err)
		}
		if err := internal.RunDir(gitDir, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			_ = internal.RunDir(gitDir, "git", "worktree", "add", oldPath, oldGitBranch)
			return fmt.Errorf("error renaming git branch: %w", err)
		}
		if err := internal.RunDir(gitDir, "git", "worktree", "add", newPath, newGitBranch); err != nil {
			return fmt.Errorf("error creating new worktree: %w", err)
		}

		target := internal.ResolveInjectInto("")
		if injectErr := internal.InjectFiles(featurePath, newPath, target); injectErr != nil {
			fmt.Printf("Warning: inject failed: %v\n", injectErr)
		}
	} else {
		// Archived: just rename the git branch
		if err := internal.RunDir(gitDir, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			return fmt.Errorf("error renaming git branch: %w", err)
		}
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		return fmt.Errorf("error saving stack: %w", err)
	}

	// Kill stale tmux session
	oldSession := sanitizeSessionName(feature + "/" + oldName)
	if sessionExists(oldSession) {
		_ = internal.RunSilent("tmux", "kill-session", "-t", oldSession)
	}

	// Update decisions.yaml branch references
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

// resolveGitDir finds a usable git directory from the feature's worktrees.
// Returns the path to an active worktree, or tries cwd as fallback.
func resolveGitDir(featurePath string, stack internal.Stack) string {
	// Try active worktrees first
	for _, entry := range stack.Branches {
		wtPath := internal.WorktreePath("", entry.Name)
		// Reconstruct from featurePath directly
		path := featurePath + "/worktrees/" + entry.Name
		if _, err := os.Stat(path); err == nil {
			return path
		}
		if entry.Repo != "" {
			return entry.Repo
		}
		_ = wtPath
	}

	// Fallback: try cwd
	if internal.BranchExists("HEAD") {
		cwd, _ := os.Getwd()
		return cwd
	}

	return ""
}

package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase worktrees in dependency order",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return fmt.Errorf("sync requires linked worktrees; not supported in checkout mode")
			}

			feature := args[0]
			featurePath := internal.FeaturePath(feature)

			if abort {
				return handleSyncAbort(feature, featurePath)
			}
			if cont {
				return handleSyncContinue(feature, featurePath, push)
			}
			if internal.HasSyncState(featurePath) {
				state, _ := internal.LoadSyncState(featurePath)
				return fmt.Errorf("previous sync incomplete (failed on: %s); use --continue or --abort", state.FailedBranch)
			}

			result := syncFeature(feature, verbose)
			if !result.Complete {
				return fmt.Errorf("sync incomplete")
			}
			fmt.Println("Sync complete.")
			if push {
				fmt.Println("\nPushing...")
				pushFeature(feature, false)
			}
			return nil
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")

	return cmd
}

func handleSyncAbort(feature, featurePath string) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	}
	if state.FailedBranch != "" {
		path := internal.WorktreePath(feature, state.FailedBranch)
		if isRebaseInProgress(path) {
			_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
		}
	}
	internal.DeleteSyncState(featurePath)
	fmt.Println("Sync state cleared.")
	return nil
}

func handleSyncContinue(feature, featurePath string, push bool) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := internal.WorktreePath(feature, state.FailedBranch)
	if state.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", state.FailedBranch)
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	if state.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, state.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", state.FailedBranch)
		}
		if !branchContainsConfiguredParent(feature, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))
	}

	done := make(map[string]bool)
	for _, name := range state.Completed {
		done[name] = true
	}
	if state.FailedBranch != "" {
		done[state.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(state.Pending))
	result := syncWithStackFiltered(feature, featurePath, stack, sorted, done)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		pushFeature(feature, false)
	}
	return nil
}

func branchContainsConfiguredParent(feature string, stack internal.Stack, child internal.StackEntry) bool {
	parent := internal.GetBranch(stack, child.Base)
	if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
		return true
	}
	path := internal.WorktreePath(feature, child.Name)
	return internal.RunSilentDir(path, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) == nil
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

func syncFeature(feature string, verbose bool) syncResult {
	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		fetchQuiet("", "", verbose)
		syncFallback(featurePath)
		return syncResult{Complete: true}
	}

	repos := internal.UniqueRepos(stack, featurePath)
	for repo, wtPath := range repos {
		fetchQuiet(repo, wtPath, verbose)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStack(feature, featurePath, stack, sorted)
}

func fetchQuiet(repo, wtPath string, verbose bool) {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	if verbose {
		fmt.Printf("Fetching %s...\n", label)
		if wtPath != "" {
			_ = internal.RunDir(wtPath, "git", "fetch")
		} else if repo != "" {
			_ = internal.RunDir(repo, "git", "fetch")
		} else {
			_ = internal.Run("git", "fetch")
		}
	} else {
		fmt.Printf("Fetching %s... ", label)
		var err error
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Println("failed")
		} else {
			fmt.Println("done")
		}
	}
}

package internal

import (
	"maps"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Workspaces    map[string]string `yaml:"workspaces"`
	AgentCommand  string            `yaml:"agent_command"`
	UseTmux       *bool             `yaml:"use_tmux"`
	InjectInto    string            `yaml:"inject_into"`
	TestCommand   string            `yaml:"test_command"`
	AutoHooks     *bool             `yaml:"auto_hooks"`
	BranchPrefix  string            `yaml:"branch_prefix"`
	WorkspaceMode string            `yaml:"workspace_mode,omitempty"`
}

func (c Config) GetAgentCommand() string {
	if c.AgentCommand != "" {
		return c.AgentCommand
	}
	return "claude"
}

// ConfigPath returns the global config path.
func ConfigPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tws", "config.yaml")
}

func repoConfigPath() string {
	root, err := RepoRoot()
	if err != nil {
		return ""
	}
	return filepath.Join(root, ".tws", "config.yaml")
}

func loadConfigFile(path string) Config {
	if path == "" {
		return Config{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}
	}
	return cfg
}

// LoadConfig loads the global config, then merges per-repo config on top.
// Per-repo values override global values when set.
func LoadConfig() Config {
	cfg := loadConfigFile(ConfigPath())
	repo := loadConfigFile(repoConfigPath())

	if repo.AgentCommand != "" {
		cfg.AgentCommand = repo.AgentCommand
	}
	if repo.UseTmux != nil {
		cfg.UseTmux = repo.UseTmux
	}
	if repo.InjectInto != "" {
		cfg.InjectInto = repo.InjectInto
	}
	if repo.TestCommand != "" {
		cfg.TestCommand = repo.TestCommand
	}
	if repo.AutoHooks != nil {
		cfg.AutoHooks = repo.AutoHooks
	}
	if repo.BranchPrefix != "" {
		cfg.BranchPrefix = repo.BranchPrefix
	}
	if repo.WorkspaceMode != "" {
		cfg.WorkspaceMode = repo.WorkspaceMode
	}
	if len(repo.Workspaces) > 0 {
		if cfg.Workspaces == nil {
			cfg.Workspaces = make(map[string]string)
		}
		maps.Copy(cfg.Workspaces, repo.Workspaces)
	}

	return cfg
}

// SaveConfigFile writes a config to the given path.
func SaveConfigFile(path string, cfg Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := yaml.Marshal(&cfg)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// RepoConfigPath exports the per-repo config path for the config command.
func RepoConfigPath() string {
	return repoConfigPath()
}

// LoadConfigFile loads a single config file (exported for the config command).
func LoadConfigFile(path string) Config {
	return loadConfigFile(path)
}

// LoadRepoConfig loads a per-repo config from the given path.
func LoadRepoConfig(path string) Config {
	return loadConfigFile(path)
}

// SaveRepoConfig writes a per-repo config to the given path.
func SaveRepoConfig(path string, cfg Config) error {
	return SaveConfigFile(path, cfg)
}

// TemplatePath returns the template directory path.
// Per-repo (.tws/templates/) takes priority over global (~/.config/tws/templates/).
// Returns empty string if neither exists.
func TemplatePath() string {
	// Per-repo first
	repoPath := repoConfigPath()
	if repoPath != "" {
		repoTemplates := filepath.Join(filepath.Dir(repoPath), "templates")
		if info, err := os.Stat(repoTemplates); err == nil && info.IsDir() {
			return repoTemplates
		}
	}

	// Global
	home, _ := os.UserHomeDir()
	globalTemplates := filepath.Join(home, ".config", "tws", "templates")
	if info, err := os.Stat(globalTemplates); err == nil && info.IsDir() {
		return globalTemplates
	}

	return ""
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

type StackEntry struct {
	Name        string `yaml:"name"`
	Branch      string `yaml:"branch,omitempty"`   // git branch name (defaults to Name if empty)
	Archived    bool   `yaml:"archived,omitempty"` // true when branch is archived (metadata only)
	Base        string `yaml:"base"`
	Repo        string `yaml:"repo,omitempty"`          // source repo path (empty = default/current repo)
	LastBaseSHA string `yaml:"last_base_sha,omitempty"` // SHA of base branch at last sync
}

// GitBranch returns the actual git branch name for this entry.
func (e StackEntry) GitBranch() string {
	if e.Branch != "" {
		return e.Branch
	}
	return e.Name
}

type Stack struct {
	Branches []StackEntry `yaml:"branches"`
}

// UniqueRepos returns a set of unique repo paths referenced in the stack.
// Empty string represents the default repo. Returns worktree paths for
// each repo (to use as git context) alongside the repo path.
func UniqueRepos(s Stack, featurePath string) map[string]string {
	repos := make(map[string]string)
	for _, e := range s.Branches {
		repo := e.Repo
		if _, ok := repos[repo]; !ok {
			// Find an active worktree from this repo to use as git context
			wtPath := filepath.Join(featurePath, "worktrees", e.Name)
			if _, err := os.Stat(wtPath); err == nil {
				repos[repo] = wtPath
			} else {
				repos[repo] = "" // no active worktree, will need fallback
			}
		}
	}
	return repos
}

// HasBranch checks if a branch name already exists in the stack.
func HasBranch(s Stack, name string) bool {
	for _, e := range s.Branches {
		if e.Name == name {
			return true
		}
	}
	return false
}

// GetBranch returns the StackEntry for a branch name. Returns empty entry if not found.
func GetBranch(s Stack, name string) StackEntry {
	for _, e := range s.Branches {
		if e.Name == name {
			return e
		}
	}
	return StackEntry{}
}

// UpdateBaseSHA updates the last_base_sha for a branch in the stack.
func UpdateBaseSHA(s *Stack, branchName, sha string) {
	for i := range s.Branches {
		if s.Branches[i].Name == branchName {
			s.Branches[i].LastBaseSHA = sha
			return
		}
	}
}

// GetBranchSHA returns the current HEAD SHA of a branch using git.
func GetBranchSHA(gitContext, branch string) string {
	args := []string{"rev-parse", branch}
	if gitContext != "" {
		args = []string{"-C", gitContext, "rev-parse", branch}
	}
	out, err := exec.Command("git", args...).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// RenameBranch renames a branch in the stack, updating both Name and Base references.
func RenameBranch(s *Stack, oldName, newName string) bool {
	found := false
	for i := range s.Branches {
		if s.Branches[i].Name == oldName {
			s.Branches[i].Name = newName
			found = true
		}
		if s.Branches[i].Base == oldName {
			s.Branches[i].Base = newName
		}
	}
	return found
}

func StackPath(featurePath string) string {
	return filepath.Join(featurePath, "stack.yaml")
}

func LoadStack(featurePath string) (Stack, error) {
	data, err := os.ReadFile(StackPath(featurePath))
	if err != nil {
		return Stack{}, err
	}
	var s Stack
	if err := yaml.Unmarshal(data, &s); err != nil {
		return Stack{}, err
	}
	return s, nil
}

func SaveStack(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return os.WriteFile(StackPath(featurePath), data, 0644)
}

// TopoSort returns branches in dependency order (parents before children).
// Returns an error if the graph contains a cycle.
func TopoSort(s Stack) ([]StackEntry, error) {
	// Build adjacency: base → children
	entryMap := make(map[string]StackEntry)
	children := make(map[string][]string)
	inDegree := make(map[string]int)

	for _, e := range s.Branches {
		entryMap[e.Name] = e
		inDegree[e.Name] = 0
	}

	for _, e := range s.Branches {
		// Only count edges where the base is also a tracked branch
		if _, ok := entryMap[e.Base]; ok {
			children[e.Base] = append(children[e.Base], e.Name)
			inDegree[e.Name]++
		}
	}

	// Kahn's algorithm
	var queue []string
	for name, deg := range inDegree {
		if deg == 0 {
			queue = append(queue, name)
		}
	}

	var sorted []StackEntry
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		sorted = append(sorted, entryMap[name])
		for _, child := range children[name] {
			inDegree[child]--
			if inDegree[child] == 0 {
				queue = append(queue, child)
			}
		}
	}

	if len(sorted) != len(s.Branches) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	return sorted, nil
}

// Descendants returns all transitive children of the given branch.
func Descendants(s Stack, branch string) map[string]bool {
	children := make(map[string][]string)
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
	}

	result := make(map[string]bool)
	queue := []string{branch}
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		for _, child := range children[name] {
			if !result[child] {
				result[child] = true
				queue = append(queue, child)
			}
		}
	}
	return result
}

// PrintTree prints the stack as an indented dependency tree.
func PrintTree(s Stack) {
	children := make(map[string][]string)
	roots := make(map[string]bool)

	for _, e := range s.Branches {
		roots[e.Name] = true
	}
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
		// If base is a tracked branch, this entry is not a root
		for _, other := range s.Branches {
			if other.Name == e.Base {
				delete(roots, e.Name)
				break
			}
		}
	}

	var printNode func(name, prefix string, isLast bool)
	printNode = func(name, prefix string, isLast bool) {
		connector := "├── "
		if isLast {
			connector = "└── "
		}
		fmt.Println(prefix + connector + name)

		childPrefix := prefix
		if isLast {
			childPrefix += "    "
		} else {
			childPrefix += "│   "
		}

		kids := children[name]
		for i, child := range kids {
			printNode(child, childPrefix, i == len(kids)-1)
		}
	}

	// Print from each root's base (usually "main")
	bases := make(map[string]bool)
	for _, e := range s.Branches {
		if roots[e.Name] {
			bases[e.Base] = true
		}
	}

	for base := range bases {
		fmt.Printf("(%s)\n", base)
		kids := children[base]
		for i, child := range kids {
			printNode(child, "", i == len(kids)-1)
		}
	}

	if len(s.Branches) == 0 {
		fmt.Println("No branches tracked. Use 'ts new <feature> <branch>' to add branches.")
	}
}

// FormatBranchStatus formats a branch sync result for display.
func FormatBranchStatus(name, status string) string {
	symbols := map[string]string{
		"synced":  "+",
		"failed":  "x",
		"skipped": "-",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s", sym, name)
}

// DescendantsList returns Descendants as a sorted display string.
func DescendantsList(s Stack, branch string) string {
	descs := Descendants(s, branch)
	var names []string
	for name := range descs {
		names = append(names, name)
	}
	return strings.Join(names, ", ")
}

package internal

import (
	"crypto/sha256"
	"fmt"
	"os"
	"path/filepath"
)

// WorkspaceMode describes how tws stores metadata for a repository.
type WorkspaceMode string

const (
	// ModeExternal stores metadata in a sibling directory (<repo>.tws).
	// This is the default and preserves the original behaviour.
	ModeExternal WorkspaceMode = "external"

	// ModeCheckout stores metadata inside the repository at <repo>/.tws.
	ModeCheckout WorkspaceMode = "checkout"
)

// Capabilities reports what features a given workspace mode supports.
// Checkout mode retains logical stacks and decisions but cannot create
// linked worktrees because it stores metadata inside the repo tree.
type Capabilities struct {
	Stack           bool // logical stack/decisions
	LinkedWorktrees bool // git worktree add support
}

// Workspace is the resolved identity and layout for a single repository.
type Workspace struct {
	// RepoRoot is the absolute, cleaned repository path.
	RepoRoot string

	// Mode is the resolved workspace mode (external or checkout).
	Mode WorkspaceMode

	// MetadataRoot is the absolute path that holds tws state.
	// External: <repo>.tws   Checkout: <repo>/.tws
	MetadataRoot string

	// StableID is a deterministic identifier derived from the canonical
	// repo path. Movement of the repository on disk will change this
	// value until a global registry supplies persisted IDs.
	StableID string

	// Caps describes mode-specific capabilities.
	Caps Capabilities
}

// capsFor returns capabilities for a given mode.
func capsFor(mode WorkspaceMode) Capabilities {
	switch mode {
	case ModeCheckout:
		return Capabilities{Stack: true, LinkedWorktrees: false}
	default: // external
		return Capabilities{Stack: true, LinkedWorktrees: true}
	}
}

// stableID computes a deterministic hex ID from a canonical path.
// It uses the absolute, cleaned path (with symlinks resolved when
// possible). Relocating the repository changes the ID; a future
// global registry will provide persistent identifiers.
func stableID(canonicalPath string) string {
	h := sha256.Sum256([]byte(canonicalPath))
	return fmt.Sprintf("%x", h[:8])
}

// canonicalize returns an absolute, cleaned path. It resolves symlinks
// when possible; on error it falls back to filepath.Abs + filepath.Clean.
func canonicalize(p string) string {
	if resolved, err := filepath.EvalSymlinks(p); err == nil {
		return filepath.Clean(resolved)
	}
	return cleanAbsolute(p)
}

func cleanAbsolute(p string) string {
	abs, err := filepath.Abs(p)
	if err != nil {
		return filepath.Clean(p)
	}
	return filepath.Clean(abs)
}

// parseMode interprets a raw string as a WorkspaceMode.
// Unknown values return empty string and false.
func parseMode(raw string) (WorkspaceMode, bool) {
	switch WorkspaceMode(raw) {
	case ModeExternal:
		return ModeExternal, true
	case ModeCheckout:
		return ModeCheckout, true
	case "":
		return "", false
	default:
		return "", false
	}
}

// ResolveCurrentWorkspace determines the workspace for a given repo root
// and config. It checks, in order:
//
//  1. Explicit workspace_mode in the per-repo config (.tws/config.yaml).
//  2. Presence of .tws/config.yaml without workspace_mode -> external (legacy).
//  3. Default: external.
//
// This function is a pure resolver; it never calls TwsRoot or any path
// function that might recurse back into resolution.
func ResolveCurrentWorkspace(repoRoot string, cfg Config) Workspace {
	original := cleanAbsolute(repoRoot)
	canon := canonicalize(repoRoot)

	// Read per-repo config to look for explicit workspace_mode.
	repoConfigFile := filepath.Join(canon, ".tws", "config.yaml")
	repoCfg := loadConfigFile(repoConfigFile)

	var mode WorkspaceMode
	if m, ok := parseMode(repoCfg.WorkspaceMode); ok {
		mode = m
	} else {
		// Legacy: .tws/config.yaml exists but no workspace_mode -> external.
		// Or no config at all -> external.
		mode = ModeExternal
	}

	var metadataRoot string
	switch mode {
	case ModeCheckout:
		metadataRoot = filepath.Join(canon, ".tws")
	default: // external
		metadataRoot = resolveExternalRoot(original, canon, cfg)
	}

	return Workspace{
		RepoRoot:     canon,
		Mode:         mode,
		MetadataRoot: metadataRoot,
		StableID:     stableID(canon),
		Caps:         capsFor(mode),
	}
}

// resolveExternalRoot computes the external metadata root for a repo.
// Priority: original-path config key -> canonical-path config key -> sibling directory.
// This preserves legacy config entries that intentionally use a symlinked repo path.
func resolveExternalRoot(originalRepoRoot, canonicalRepoRoot string, cfg Config) string {
	if root, ok := cfg.Workspaces[originalRepoRoot]; ok {
		return root
	}
	if root, ok := cfg.Workspaces[canonicalRepoRoot]; ok {
		return root
	}
	return canonicalRepoRoot + ".tws"
}

// FeaturePath returns the feature directory within the workspace.
func (w Workspace) FeaturePath(feature string) string {
	return filepath.Join(w.MetadataRoot, feature)
}

// WorktreePath returns the worktree directory within a feature.
func (w Workspace) WorktreePath(feature, worktree string) string {
	return filepath.Join(w.MetadataRoot, feature, "worktrees", worktree)
}

// resolveWorkspaceMetadataRoot is the backend boundary function.
// It resolves the metadata root for a given repo, accounting for
// workspace mode. Called by resolveTwsRoot to route through the
// workspace layer while preserving byte-for-byte external outputs.
//
// If repoRoot is empty or repoErr is non-nil, this returns empty
// string (caller should fall back to home dir or env override).
func resolveWorkspaceMetadataRoot(repoRoot string, repoErr error, cfg Config) string {
	if repoErr != nil || repoRoot == "" {
		return ""
	}
	ws := ResolveCurrentWorkspace(repoRoot, cfg)
	return ws.MetadataRoot
}

// metadataRootExists checks if the metadata root directory exists on disk.
func metadataRootExists(root string) bool {
	info, err := os.Stat(root)
	return err == nil && info.IsDir()
}

// ResolveCurrentWorkspaceE is an error-returning resolver for use in CLI
// commands. Unlike ResolveCurrentWorkspace (which silently defaults to
// external mode), this function returns an error when the per-repo config
// contains an invalid workspace_mode value.
func ResolveCurrentWorkspaceE(repoRoot string, cfg Config) (Workspace, error) {
	original := cleanAbsolute(repoRoot)
	canon := canonicalize(repoRoot)

	repoConfigFile := filepath.Join(canon, ".tws", "config.yaml")
	repoCfg := loadConfigFile(repoConfigFile)

	var mode WorkspaceMode
	if repoCfg.WorkspaceMode != "" {
		m, ok := parseMode(repoCfg.WorkspaceMode)
		if !ok {
			return Workspace{}, fmt.Errorf("invalid workspace_mode %q in %s", repoCfg.WorkspaceMode, repoConfigFile)
		}
		mode = m
	} else {
		mode = ModeExternal
	}

	var metadataRoot string
	switch mode {
	case ModeCheckout:
		metadataRoot = filepath.Join(canon, ".tws")
	default:
		metadataRoot = resolveExternalRoot(original, canon, cfg)
	}

	return Workspace{
		RepoRoot:     canon,
		Mode:         mode,
		MetadataRoot: metadataRoot,
		StableID:     stableID(canon),
		Caps:         capsFor(mode),
	}, nil
}

// RequireWorkspace resolves the workspace for the current repo root,
// returning a stable CLI error if the repo root cannot be determined
// or the workspace mode is invalid. Commands should use this instead
// of silently ignoring errors from MainRepoRoot or ResolveCurrentWorkspace.
func RequireWorkspace() (Workspace, error) {
	repoRoot, err := MainRepoRoot()
	if err != nil {
		return Workspace{}, fmt.Errorf("not inside a git repository")
	}
	cfg := LoadConfig()
	return ResolveCurrentWorkspaceE(repoRoot, cfg)
}
